describe('Login Page - Password Validation', () => {
  beforeEach(() => {
    cy.visit('https://the-internet.herokuapp.com/login');
  });

  it('should display error message when submitting wrong password', () => {
    cy.get('[name="username"]').type('tomsmith');
    cy.get('[name="password"]').type('wrongpassword');
    cy.get('[type="submit"]').click();

    cy.get('#flash-messages').should('be.visible');
    cy.get('#flash-messages').should('contain', 'Your password is invalid!');
    cy.get('#flash-messages').should('have.class', 'flash-error');
    cy.url().should('include', '/login');
  });

  it('should not display error message when submitting correct credentials', () => {
    cy.get('[name="username"]').type('tomsmith');
    cy.get('[name="password"]').type('Password123!');
    cy.get('[type="submit"]').click();

    cy.url().should('include', '/secure');
    cy.get('#flash-messages').should('not.exist');
  });
});
